"""Shared utilities to avoid circular imports between app and routes."""
from functools import wraps
from flask import session, redirect, url_for, flash
from database import db_session
from models import AuditLog
from datetime import datetime, UTC


def _utcnow\(\):
    """Return current UTC as naive datetime \(SQLite compat\)."""
    return datetime.now\(UTC\).replace\(tzinfo=None\)


def login_required\(f\):
    """Decorator to require login."""
    @wraps\(f\)
    def decorated_function\(*args, **kwargs\):
        if not session.get\("logged_in"\):
            flash\("Please log in to access this page.", "error"\)
            return redirect\(url_for\("auth.login"\)\)
        return f\(*args, **kwargs\)
    return decorated_function


def role_required\(allowed_roles\):
    """Decorator to require specific roles."""
    def decorator\(f\):
        @wraps\(f\)
        def decorated_function\(*args, **kwargs\):
            if not session.get\("logged_in"\):
                return redirect\(url_for\("auth.login"\)\)
            if session.get\("role"\) not in allowed_roles:
                return "Access denied", 403
            return f\(*args, **kwargs\)
        return decorated_function
    return decorator


def log_audit\(action, entity_type, entity_id=None, details=None\):
    """Log an action to the audit log."""
    try:
        audit = AuditLog\(
            action=action,
            entity_type=entity_type,
            entity_id=entity_id,
            details=details,
            username=session.get\("username", "system"\),
            timestamp=_utcnow\(\)
        \)
        db_session.add\(audit\)
        db_session.commit\(\)
    except Exception as e:
        print\(f"Failed to log audit: {e}"\)
        db_session.rollback\(\)


# Re-export db_session for convenience
__all__ = ["_utcnow", "login_required", "role_required", "log_audit", "db_session"]
