import ast
import os
from collections import defaultdict

def analyze_imports\(filepath\):
    """Analyze imports in a Python file."""
    with open\(filepath, 'r'\) as f:
        try:
            tree = ast.parse\(f.read\(\)\)
        except:
            return []

    imports = []
    for node in ast.walk\(tree\):
        if isinstance\(node, ast.ImportFrom\):
            if node.module:
                imports.append\(\('from', node.module, [n.name for n in node.names]\)\)
        elif isinstance\(node, ast.Import\):
            for n in node.names:
                imports.append\(\('import', n.name, []\)\)
    return imports

# Analyze app.py
print\("=== app.py imports from routes ==="\)
app_imports = analyze_imports\('app.py'\)
for imp_type, module, names in app_imports:
    if module and module.startswith\('routes'\):
        print\(f"  {module}: {names}"\)

print\("\\n=== Route files imports from app ==="\)
for filename in sorted\(os.listdir\('routes'\)\):
    if filename.endswith\('.py'\):
        filepath = os.path.join\('routes', filename\)
        imports = analyze_imports\(filepath\)
        app_imports = [\(m, n\) for t, m, n in imports if m == 'app']
        if app_imports:
            print\(f"\\n{filename}:"\)
            for module, names in app_imports:
